if(typeof require==='function'){var Classy=require('./classy');}var Currency=Classy.newClass().name('Currency');Currency.fields({data:{playerId:null,gold:0,diamonds:0}});Currency.constructor(function(){});Currency.constructor('withObject',function(obj){this.data=obj;});Currency.methods({getPlayerId:function(){return this.data.playerId;},getGold:function(){return this.data.gold;},getDiamonds:function(){return this.data.diamonds;},toObj:function(){return this.data;}});if(typeof module==='object'){module.exports=Currency;}